import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:go_router/go_router.dart';
import '../../data/mock/seed_data.dart'; import '../../models/field_definition.dart'; import '../../state/providers.dart';
class FieldSchemaSetupScreen extends ConsumerStatefulWidget { const FieldSchemaSetupScreen({super.key, required this.familyId}); final String familyId; @override ConsumerState<FieldSchemaSetupScreen> createState()=>_S();} class _S extends ConsumerState<FieldSchemaSetupScreen>{ final selected=<FieldDefinition>[]; final label=TextEditingController(); String type='text'; @override Widget build(BuildContext context){ final fam=ref.watch(familyProvider(widget.familyId)).valueOrNull; final schema=fam==null?null:ref.watch(schemaProvider(fam.fieldSchemaId)).valueOrNull; final sugg=suggestedFields(); return Scaffold(appBar: AppBar(title: const Text('Field Schema Setup')), body: ListView(padding: const EdgeInsets.all(16), children:[const Text('Locked defaults'), Wrap(children:[for(final f in defaultFields()) Chip(avatar: const Icon(Icons.lock, size: 16), label: Text(f.label))]), const Divider(), const Text('Suggested fields'), Wrap(spacing:8, children:[for(final f in sugg) FilterChip(label: Text(f.sensitive?'${f.label} 🔒':f.label), selected:selected.any((x)=>x.key==f.key), onSelected:(v)=>setState(()=>v?selected.add(f):selected.removeWhere((x)=>x.key==f.key)))]), const Divider(), Row(children:[Expanded(child: TextField(controller: label, decoration: const InputDecoration(labelText:'Custom label'))), const SizedBox(width:8), DropdownButton<String>(value:type, items: const ['text','textarea','number','date','time','email','phone','enum','image'].map((e)=>DropdownMenuItem(value:e, child:Text(e))).toList(), onChanged:(v)=>setState(()=>type=v!)), IconButton(onPressed:(){if(label.text.trim().isNotEmpty)setState(()=>selected.add(FieldDefinition(key: label.text.trim().toLowerCase().replaceAll(' ','_'), label: label.text.trim(), type: type)));}, icon: const Icon(Icons.add))]), FilledButton(onPressed: fam==null||schema==null?null:() async{ await ref.read(repositoryProvider).saveSchema(FieldSchema(id:schema.id,familyId:widget.familyId,fields:[...defaultFields(),...selected],version:schema.version)); if(context.mounted)context.go('/family/${widget.familyId}/tree');}, child: const Text('Continue'))]));}}
